forbid (
    principal is User,
    action == Action::"approveInvoice",
    resource is Invoice
)
when {
    (principal.roles.contains(Role::"Approver") ||
     principal.roles.contains(Role::"FinanceManager")) &&
    context.isBusinessHours &&
    !resource.lineItemCountCrossesThreshold &&
    resource.status == InvoiceStatus::"Unsubmitted"
};"}
